fn split_and_append(list: &Vec<i32>, n: usize) -> Vec<i32> {
    // Create a new vector to hold the result
    let mut new_list = Vec::with_capacity(list.len());
    
    // Append the slice from index n to the end of the list
    new_list.extend_from_slice(&list[n..]);
    
    // Append the slice from the start of the list to index n
    new_list.extend_from_slice(&list[0..n]);
    
    new_list
}